// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "./interfaces/ISovranWealthFund.sol";

contract SWFIntegratedEngine {
    // Admin
    address public admin;

    // Token contract
    IERC20 public swfToken;

    // APR settings
    uint256 public aprBasisPoints = 2500; // 25% APR (in basis points)
    uint256 public constant BPS_DIVISOR = 10000;
    uint256 public constant SECONDS_IN_YEAR = 31536000;
    uint256 public constant MIN_STAKE_AMOUNT = 50 * 1e18; // 50 SWF minimum

    // SoloMethod Engine - 16 wallet structure
    enum WalletRole { BUYER, HOLDER, STAKER, LIQUIDITY, TRACKER }

    struct WalletInfo {
        WalletRole role;
        uint256 balance;
    }

    mapping(address => WalletInfo[16]) public userWallets;
    mapping(address => uint256) public stakedAmount;
    mapping(address => uint256) public lastRewardTime;
    mapping(address => uint256) public rewardDebt;

    // Sovereign Engine - Role distribution structure
    mapping(address => string) public roleRegistry;
    mapping(string => uint256) public roleAllocations;
    address[] public recipients;

    // Events
    event APRUpdated(uint256 oldAPR, uint256 newAPR);
    event Deposited(address indexed user, uint256 amount);
    event Withdrawn(address indexed user, uint256 amount);
    event Minted(address indexed user, uint256 reward);
    event RoleRegistered(address indexed wallet, string role, uint256 percentage);

    constructor(address _swfTokenAddress) {
        admin = msg.sender;
        swfToken = IERC20(_swfTokenAddress);

        // Initialize with a single role to avoid checksum issues
        _register(msg.sender, "Main Distributor", 100);
    }

    // Modifier for admin-only functions
    modifier onlyAdmin() {
        require(msg.sender == admin, "Only admin can call");
        _;
    }

    //---------------------------
    // SOLO METHOD ENGINE FUNCTIONS
    //---------------------------

    /// @notice Set a new APR value (in basis points)
    /// @param _newAprBps The new APR in basis points (100 = 1%)
    function setAPR(uint256 _newAprBps) external onlyAdmin {
        require(_newAprBps <= 5000, "APR too high (max 50%)");
        uint256 oldApr = aprBasisPoints;
        aprBasisPoints = _newAprBps;
        emit APRUpdated(oldApr, _newAprBps);
    }

    /// @notice Stake tokens and distribute them across 16 wallets
    function deposit(uint256 amount) external {
        require(amount >= MIN_STAKE_AMOUNT, "Minimum 50 SWF required");
        require(swfToken.transferFrom(msg.sender, address(this), amount), "Transfer failed");

        // Update rewards before changing stake
        _updateRewards(msg.sender);

        // Distribute the amount across 16 wallets evenly
        for (uint8 i = 0; i < 16; i++) {
            userWallets[msg.sender][i] = WalletInfo(WalletRole(i % 5), amount / 16);
        }

        stakedAmount[msg.sender] += amount;
        lastRewardTime[msg.sender] = block.timestamp;
        emit Deposited(msg.sender, amount);
    }

    /// @notice Withdraw staked tokens
    function withdraw(uint256 amount) external {
        require(amount > 0, "Amount must be greater than 0");
        require(stakedAmount[msg.sender] >= amount, "Insufficient staked balance");

        // Update rewards before changing stake
        _updateRewards(msg.sender);

        // Update staked amount
        stakedAmount[msg.sender] -= amount;

        // Reset wallet distribution
        if (stakedAmount[msg.sender] > 0) {
            // Recalculate wallets with new amount
            uint256 amountPerWallet = stakedAmount[msg.sender] / 16;
            for (uint8 i = 0; i < 16; i++) {
                userWallets[msg.sender][i].balance = amountPerWallet;
            }
        } else {
            // Clear all wallets if fully withdrawn
            for (uint8 i = 0; i < 16; i++) {
                userWallets[msg.sender][i].balance = 0;
            }
        }

        // Transfer SWF tokens back to user
        require(swfToken.transfer(msg.sender, amount), "Transfer failed");
        emit Withdrawn(msg.sender, amount);
    }

    /// @notice Update user's reward debt for precise tracking
    function _updateRewards(address user) internal {
        uint256 pending = calculateRewards(user);
        rewardDebt[user] = pending;
        lastRewardTime[user] = block.timestamp;
    }

    /// @notice Calculate earned rewards with continuous compounding
    function calculateRewards(address user) public view returns (uint256) {
        if (stakedAmount[user] == 0 || lastRewardTime[user] == 0) {
            return rewardDebt[user];
        }

        uint256 timeElapsed = block.timestamp - lastRewardTime[user];

        // Calculate reward: staked * APR * (timeElapsed / SECONDS_IN_YEAR)
        uint256 reward = (stakedAmount[user] * aprBasisPoints * timeElapsed) / 
                        BPS_DIVISOR / SECONDS_IN_YEAR;

        return reward + rewardDebt[user];
    }

    /// @notice Claim accumulated rewards
    function claimRewards() public {
        _updateRewards(msg.sender);
        uint256 reward = rewardDebt[msg.sender];

        if (reward > 0) {
            rewardDebt[msg.sender] = 0;

            // Transfer rewards to user (requires contract to have minter role)
            ISovranWealthFund swfTokenMinter = ISovranWealthFund(address(swfToken));
            swfTokenMinter.mint(msg.sender, reward);
            emit Minted(msg.sender, reward);
        }
    }

    /// @notice Get the distribution of tokens across 16 wallets
    function getWalletBreakdown(address user) external view returns (WalletInfo[16] memory) {
        return userWallets[user];
    }

    /// @notice Get total staked amount for a user
    function getTotalStaked(address user) external view returns (uint256) {
        return stakedAmount[user];
    }

    /// @notice Get pending rewards for a user
    function getPendingRewards(address user) external view returns (uint256) {
        return calculateRewards(user);
    }

    /// @notice Get current APR in percentage (25% = 2500 basis points)
    function getCurrentAPR() external view returns (uint256) {
        return aprBasisPoints;
    }

    //---------------------------
    // SOVEREIGN ENGINE FUNCTIONS
    //---------------------------

    /// @notice Register a wallet with a role and percentage allocation
    function _register(address wallet, string memory role, uint256 percentage) internal {
        roleRegistry[wallet] = role;
        roleAllocations[role] = percentage;
        recipients.push(wallet);
        emit RoleRegistered(wallet, role, percentage);
    }

    /// @notice Get the list of all registered recipients
    function getRecipientList() external view returns (address[] memory) {
        return recipients;
    }

    /// @notice Get the role of a specific wallet
    function getRole(address wallet) public view returns (string memory) {
        return roleRegistry[wallet];
    }

    /// @notice Get the percentage allocation for a specific role
    function getAllocationByRole(string memory role) public view returns (uint256) {
        return roleAllocations[role];
    }

    /// @notice Find an address by its role
    function getAddressByRole(string memory role) public view returns (address) {
        for (uint i = 0; i < recipients.length; i++) {
            if (keccak256(bytes(roleRegistry[recipients[i]])) == keccak256(bytes(role))) {
                return recipients[i];
            }
        }
        return address(0);
    }

    /// @notice Distribute tokens to all recipients according to their percentage allocations
    function distributeTokens(uint256 amount) external onlyAdmin {
        require(amount > 0, "Amount must be greater than 0");

        // Check if contract has permission to transfer the tokens
        uint256 total = 0;

        for (uint i = 0; i < recipients.length; i++) {
            string memory role = roleRegistry[recipients[i]];
            uint256 percentage = roleAllocations[role];
            uint256 allocation = (amount * percentage) / 100;
            total += allocation;

            require(swfToken.transferFrom(msg.sender, recipients[i], allocation), 
                    "Token distribution failed");
        }

        // Transfer any remainder (due to rounding) to the Treasury
        if (total < amount) {
            uint256 remainder = amount - total;
            address treasury = getAddressByRole("Treasury");
            require(treasury != address(0), "Treasury not found");
            require(swfToken.transferFrom(msg.sender, treasury, remainder), 
                    "Remainder transfer failed");
        }
    }
}

contracts/SWFModularEngine.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "./BasketIndex.sol";
import "./RoleRouter.sol";
import "./SoloMethodEngineV2.sol";

/**
 * @title SWFModularEngine
 * @notice Main controller contract that integrates BasketIndex, RoleRouter, and SoloMethodEngineV2
 * @dev Provides a single interface for managing all aspects of the Sovran Wealth Fund ecosystem
 */
contract SWFModularEngine is Ownable {
    // Core token
    IERC20 public swfToken;

    // Component contracts
    BasketIndex public basketIndex;
    RoleRouter public roleRouter;
    SoloMethodEngineV2 public stakingEngine;

    // Component status
    bool public basketIndexInitialized;
    bool public roleRouterInitialized;
    bool public stakingEngineInitialized;

    // Events
    event ComponentInitialized(string name, address component);
    event BasketAssetsUpdated(address[] assets, uint256[] weights);
    event RolesUpdated(address[] wallets, string[] roles, uint256[] shares);
    event APRUpdated(uint256 oldAPR, uint256 newAPR);

    /**
     * @notice Constructs the SWFModularEngine contract
     * @param _swfToken Address of the SWF token
     */
    constructor(address _swfToken) Ownable(msg.sender) {
        require(_swfToken != address(0), "Invalid token address");
        swfToken = IERC20(_swfToken);
    }

    // ---------- Component Initialization Functions ----------

    /**
     * @notice Initialize or update the BasketIndex component
     * @param _basketIndex Address of the BasketIndex contract
     */
    function initializeBasketIndex(address _basketIndex) external onlyOwner {
        require(_basketIndex != address(0), "Invalid address");
        basketIndex = BasketIndex(_basketIndex);
        basketIndexInitialized = true;
        emit ComponentInitialized("BasketIndex", _basketIndex);
    }

    /**
     * @notice Initialize or update the RoleRouter component
     * @param _roleRouter Address of the RoleRouter contract
     */
    function initializeRoleRouter(address _roleRouter) external onlyOwner {
        require(_roleRouter != address(0), "Invalid address");
        roleRouter = RoleRouter(_roleRouter);
        roleRouterInitialized = true;
        emit ComponentInitialized("RoleRouter", _roleRouter);
    }

    /**
     * @notice Initialize or update the SoloMethodEngineV2 component
     * @param _stakingEngine Address of the SoloMethodEngineV2 contract
     */
    function initializeStakingEngine(address _stakingEngine) external onlyOwner {
        require(_stakingEngine != address(0), "Invalid address");
        stakingEngine = SoloMethodEngineV2(_stakingEngine);
        stakingEngineInitialized = true;
        emit ComponentInitialized("StakingEngine", _stakingEngine);
    }

    // ---------- BasketIndex Management Functions ----------

    /**
     * @notice Set or update the underlying assets in the basket
     * @param assets Array of asset addresses
     * @param weights Array of weights for each asset (in basis points)
     */
    function setBasketAssets(address[] calldata assets, uint256[] calldata weights) external onlyOwner {
        require(basketIndexInitialized, "BasketIndex not initialized");
        basketIndex.setAssets(assets, weights);
        emit BasketAssetsUpdated(assets, weights);
    }

    /**
     * @notice Rebalance the assets in the basket
     */
    function rebalanceBasket() external onlyOwner {
        require(basketIndexInitialized, "BasketIndex not initialized");
        basketIndex.rebalance();
    }

    /**
     * @notice Mint basket tokens
     * @param amount Amount of basket tokens to mint
     */
    function mintBasketTokens(uint256 amount) external {
        require(basketIndexInitialized, "BasketIndex not initialized");

        // Approve all underlying assets for the basket
        address[] memory assets = basketIndex.getUnderlyingAssets();
        for (uint i = 0; i < assets.length; i++) {
            IERC20 asset = IERC20(assets[i]);

            // Calculate amount needed of this asset
            uint256 weight = basketIndex.assetWeights(assets[i]);
            uint256 assetAmount = (amount * weight) / 10000;

            // Ensure approval
            asset.approve(address(basketIndex), assetAmount);
        }

        // Mint basket tokens
        basketIndex.mint(amount);
    }

    /**
     * @notice Burn basket tokens
     * @param amount Amount of basket tokens to burn
     */
    function burnBasketTokens(uint256 amount) external {
        require(basketIndexInitialized, "BasketIndex not initialized");
        basketIndex.burn(amount);
    }

    // ---------- RoleRouter Management Functions ----------

    /**
     * @notice Set or update the roles and allocations
     * @param wallets Array of wallet addresses
     * @param roles Array of role names
     * @param shares Array of shares (in basis points)
     */
    function setRoles(address[] calldata wallets, string[] calldata roles, uint256[] calldata shares) external onlyOwner {
        require(roleRouterInitialized, "RoleRouter not initialized");
        roleRouter.setRoles(wallets, roles, shares);
        emit RolesUpdated(wallets, roles, shares);
    }

    /**
     * @notice Trigger distribution of rewards to role-based wallets
     */
    function distributeRoleRewards() external {
        require(roleRouterInitialized, "RoleRouter not initialized");

        // If there are SWF tokens in this contract, transfer them to the role router first
        uint256 balance = swfToken.balanceOf(address(this));
        if (balance > 0) {
            swfToken.approve(address(roleRouter), balance);
            swfToken.transfer(address(roleRouter), balance);
        }

        // Distribute rewards
        roleRouter.distributeRewards();
    }

    /**
     * @notice Update the main distributor address
     * @param newDistributor New main distributor address
     */
    function setMainDistributor(address newDistributor) external onlyOwner {
        require(roleRouterInitialized, "RoleRouter not initialized");
        roleRouter.setMainDistributor(newDistributor);
    }

    /**
     * @notice Update the treasury address
     * @param newTreasury New treasury address
     */
    function setTreasury(address newTreasury) external onlyOwner {
        require(roleRouterInitialized, "RoleRouter not initialized");
        roleRouter.setTreasury(newTreasury);
    }

    // ---------- Staking Engine Management Functions ----------

    /**
     * @notice Set the APR for staking rewards
     * @param newAprBps New APR in basis points (e.g., 2500 for 25%)
     */
    function setStakingAPR(uint256 newAprBps) external onlyOwner {
        require(stakingEngineInitialized, "StakingEngine not initialized");
        uint256 oldAPR = stakingEngine.getCurrentAPR();
        stakingEngine.setAPR(newAprBps);
        emit APRUpdated(oldAPR, newAprBps);
    }

    /**
     * @notice Stake tokens in the SoloMethodEngine
     * @param amount Amount to stake
     */
    function stakeTokens(uint256 amount) external {
        require(stakingEngineInitialized, "StakingEngine not initialized");

        // Approve tokens for staking
        swfToken.approve(address(stakingEngine), amount);

        // Stake tokens
        stakingEngine.deposit(amount);
    }

    /**
     * @notice Withdraw staked tokens
     * @param amount Amount to withdraw
     */
    function withdrawStakedTokens(uint256 amount) external {
        require(stakingEngineInitialized, "StakingEngine not initialized");
        stakingEngine.withdraw(amount);
    }

    /**
     * @notice Claim staking rewards
     */
    function claimStakingRewards() external {
        require(stakingEngineInitialized, "StakingEngine not initialized");
        stakingEngine.claimRewards();
    }

    // ---------- Query Functions ----------

    /**
     * @notice Get the current APR for staking
     * @return Current APR in basis points
     */
    function getCurrentAPR() external view returns (uint256) {
        require(stakingEngineInitialized, "StakingEngine not initialized");
        return stakingEngine.getCurrentAPR();
    }

    /**
     * @notice Get pending rewards for a user
     * @param user User address
     * @return Pending rewards
     */
    function getPendingRewards(address user) external view returns (uint256) {
        require(stakingEngineInitialized, "StakingEngine not initialized");
        return stakingEngine.getPendingRewards(user);
    }

    /**
     * @notice Get total staked amount for a user
     * @param user User address
     * @return Total staked amount
     */
    function getTotalStaked(address user) external view returns (uint256) {
        require(stakingEngineInitialized, "StakingEngine not initialized");
        return stakingEngine.getTotalStaked(user);
    }

    /**
     * @notice Get the wallet role for a specific address
     * @param wallet Wallet address
     * @return Role name
     */
    function getWalletRole(address wallet) external view returns (string memory) {
        require(roleRouterInitialized, "RoleRouter not initialized");
        return roleRouter.getWalletRole(wallet);
    }

    /**
     * @notice Get the wallet share for a specific address
     * @param wallet Wallet address
     * @return Share in basis points
     */
    function getWalletShare(address wallet) external view returns (uint256) {
        require(roleRouterInitialized, "RoleRouter not initialized");
        return roleRouter.getWalletShare(wallet);
    }

    /**
     * @notice Get all wallet addresses with roles
     * @return Array of wallet addresses
     */
    function getWalletRoles() external view returns (address[] memory) {
        require(roleRouterInitialized, "RoleRouter not initialized");
        return roleRouter.getWalletRoles();
    }

    /**
     * @notice Get all underlying assets in the basket
     * @return Array of asset addresses
     */
    function getBasketAssets() external view returns (address[] memory) {
        require(basketIndexInitialized, "BasketIndex not initialized");
        return basketIndex.getUnderlyingAssets();
    }

    /**
     * @notice Get the weights of all assets in the basket
     * @return Array of weights
     */
    function getBasketWeights() external view returns (uint256[] memory) {
        require(basketIndexInitialized, "BasketIndex not initialized");
        return basketIndex.getAssetWeights();
    }
}

contracts/SWFModuleIntegrator.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "./SWFModules.sol";

/**
 * @title SWFModuleIntegrator
 * @dev Central contract that manages interactions between SWF modules
 */
contract SWFModuleIntegrator is Ownable {
    // Core module references
    IERC20 public swfToken;
    LiquidityVault public liquidityVault;
    GovernanceDividendPool public governancePool;
    SWFVaultAdapter public vaultAdapter;
    address public treasury;

    // Reward distribution configuration
    uint256 public lastRewardDistribution;
    uint256 public rewardDistributionFrequency = 7 days;
    uint8 public rewardsPercentage = 50; // 50% of funds go to rewards

    // Events
    event StakedInGovernancePool(address indexed user, uint256 amount);
    event LPTokensStaked(address indexed user, uint256 amount);
    event DepositedToVault(address indexed user, uint256 amount);
    event RewardsDistributed(uint256 amount, uint256 timestamp);
    event ConfigUpdated(string parameter, uint256 value);

    /**
     * @dev Constructor - initializes the integrator with module addresses
     */
    constructor(
        address _swfToken,
        address _liquidityVault,
        address payable _governancePool,
        address _vaultAdapter,
        address _treasury
    ) Ownable(msg.sender) {
        swfToken = IERC20(_swfToken);
        liquidityVault = LiquidityVault(_liquidityVault);
        governancePool = GovernanceDividendPool(_governancePool);
        vaultAdapter = SWFVaultAdapter(_vaultAdapter);
        treasury = _treasury;
        lastRewardDistribution = block.timestamp;
    }

    /**
     * @dev Stakes SWF tokens in the governance pool
     * @param amount Amount of SWF tokens to stake
     */
    function stakeInGovernancePool(uint256 amount) external {
        require(amount > 0, "Zero amount");

        // Transfer tokens from user to this contract
        swfToken.transferFrom(msg.sender, address(this), amount);

        // Approve governance pool to spend tokens
        swfToken.approve(address(governancePool), amount);

        // Stake in governance pool
        governancePool.stake(amount);

        emit StakedInGovernancePool(msg.sender, amount);
    }

    /**
     * @dev Stakes LP tokens in the liquidity vault
     * @param amount Amount of LP tokens to stake
     */
    function stakeLPTokens(uint256 amount) external {
        require(amount > 0, "Zero amount");

        // Get LP token address from liquidity vault
        IERC20 lpToken = IERC20(liquidityVault.lpToken());

        // Transfer LP tokens from user to this contract
        lpToken.transferFrom(msg.sender, address(this), amount);

        // Approve liquidity vault to spend LP tokens
        lpToken.approve(address(liquidityVault), amount);

        // Stake in liquidity vault
        liquidityVault.stake(amount);

        emit LPTokensStaked(msg.sender, amount);
    }

    /**
     * @dev Deposits SWF tokens to the vault adapter
     * @param amount Amount of SWF tokens to deposit
     */
    function depositToVault(uint256 amount) external {
        require(amount > 0, "Zero amount");

        // Transfer tokens from user to this contract
        swfToken.transferFrom(msg.sender, address(this), amount);

        // Approve vault adapter to spend tokens
        swfToken.approve(address(vaultAdapter), amount);

        // Deposit to vault adapter
        vaultAdapter.deposit(amount);

        emit DepositedToVault(msg.sender, amount);
    }

    /**
     * @dev Forwards funds from vault adapter to the vault (treasury)
     * @param amount Amount of SWF tokens to forward
     */
    function forwardToVault(uint256 amount) external onlyOwner {
        vaultAdapter.forwardToVault(amount);
    }

    /**
     * @dev Distributes rewards from the treasury to stakers
     * Only callable by owner and after rewardDistributionFrequency has passed
     */
    function distributeRewards() external onlyOwner {
        require(
            block.timestamp >= lastRewardDistribution + rewardDistributionFrequency,
            "Too soon to distribute"
        );

        // Calculate total rewards
        uint256 treasuryBalance = swfToken.balanceOf(treasury);
        uint256 rewardAmount = (treasuryBalance * rewardsPercentage) / 100;

        // Update last distribution time
        lastRewardDistribution = block.timestamp;

        // Transfer rewards from treasury to governance pool
        require(
            swfToken.transferFrom(treasury, address(governancePool), rewardAmount),
            "Transfer failed"
        );

        emit RewardsDistributed(rewardAmount, block.timestamp);
    }

    /**
     * @dev Updates the reward distribution frequency
     * @param newFrequency New frequency in seconds
     */
    function setRewardDistributionFrequency(uint256 newFrequency) external onlyOwner {
        require(newFrequency > 0, "Invalid frequency");
        rewardDistributionFrequency = newFrequency;
        emit ConfigUpdated("rewardDistributionFrequency", newFrequency);
    }

    /**
     * @dev Updates the rewards percentage
     * @param newPercentage New percentage (0-100)
     */
    function setRewardsPercentage(uint8 newPercentage) external onlyOwner {
        require(newPercentage <= 100, "Invalid percentage");
        rewardsPercentage = newPercentage;
        emit ConfigUpdated("rewardsPercentage", newPercentage);
    }

    /**
     * @dev Gets user information across all modules
     * @param user User address to query
     * @return lpStaked LP tokens staked in liquidity vault
     * @return swfStaked SWF tokens staked in governance pool
     * @return swfDeposited SWF tokens deposited in vault adapter
     */
    function getUserInfo(address user) external view returns (
        uint256 lpStaked,
        uint256 swfStaked,
        uint256 swfDeposited
    ) {
        lpStaked = liquidityVault.staked(user);
        swfStaked = governancePool.stakes(user);
        swfDeposited = vaultAdapter.deposits(user);
        return (lpStaked, swfStaked, swfDeposited);
    }

    /**
     * @dev Gets total amount of LP tokens staked in liquidity vault
     * @return Total LP tokens staked
     */
    function getTotalLiquidityStaked() external view returns (uint256) {
        return liquidityVault.totalStaked();
    }

    /**
     * @dev Gets total amount of SWF tokens staked in governance pool
     * @return Total SWF tokens staked
     */
    function getTotalGovernanceStaked() external view returns (uint256) {
        return governancePool.totalStaked();
    }

    /**
     * @dev Gets total amount of SWF tokens deposited in vault adapter
     * @return Total SWF tokens deposited
     */
    function getTotalVaultDeposits() external view returns (uint256) {
        return vaultAdapter.totalDeposits();
    }
}

